```swift
protocol LogViewerState: Observable {
    var messages: [LogMessage] { get }
    var displayedMessages: [LogMessage] { get }
    var isLoading: Bool { get }
    var taskList: [TaskListItem] { get }
    var completedTaskCount: Int { get }
    var taskProgress: Double { get }
    var toolResultLookup: [String: String] { get }
    var pendingPrompt: LogToolCall? { get }
    var fileURL: URL { get }
    func roleLabel(_ msg: LogMessage) -> String
}

@Observable
final class LogViewerViewModel: LogViewerState, LogViewerActions {
    private(set) var completedTaskCount = 0
    private(set) var taskProgress = 0.0
    private var parseTask: Task<([LogMessage], Date?), Never>?

    deinit {
        parseTask?.cancel()
    }

    func loadMessages() async {
        parseTask?.cancel()
        let url = fileURL
        let cached = lastMtime
        let fs = fileSystem
        let parser = parser

        let task = Task(priority: .utility) {
            let attrs = try? fs.attributesOfItem(atPath: url.path)
            let mtime = attrs?[.modificationDate] as? Date
            if let cached, let mtime, cached == mtime {
                return ([], mtime)
            }
            if Task.isCancelled { return ([], mtime) }
            return (parser.parseMessages(at: url), mtime)
        }
        parseTask = task

        let (msgs, mtime) = await task.value
        guard !task.isCancelled else { return }
        parseTask = nil
        if let mtime { lastMtime = mtime }
        if !msgs.isEmpty {
            messages = msgs
            rebuildDerivedState(from: msgs)
        }
        isLoading = false
    }

    private func rebuildDerivedState(from messages: [LogMessage]) {
        // existing task reconstruction remains here
        taskList = tasks
        completedTaskCount = tasks.filter { $0.status == "completed" }.count
        taskProgress = tasks.isEmpty ? 0 : Double(completedTaskCount) / Double(tasks.count)
        toolResultLookup = lookup
        pendingPrompt = prompt
    }
}
```

