private struct DiffLine: Identifiable {
    let id = UUID()
    let prefix: String
    let text: String
    let color: Color
}

private struct DiffContentView: View {
    let filePath: String
    let lines: [DiffLine]
    let fallbackContents: [String]
    let threshold: Int

    private var isLarge: Bool { lines.count > threshold }

    var body: some View {
        VStack(alignment: .leading, spacing: isLarge ? 4 : 0) {
            if !filePath.isEmpty {
                Text(filePath)
                    .font(.system(size: 9, design: .monospaced))
                    .foregroundStyle(.tertiary)
                    .padding(.bottom, isLarge ? 0 : 4)
            }

            if isLarge {
                ForEach(Array(fallbackContents.enumerated()), id: \.offset) { _, content in
                    if !content.isEmpty { ToolResultView(content: content) }
                }
            } else {
                ForEach(lines) { line in
                    Text("\(line.prefix) \(line.text)")
                        .font(.system(size: 10, design: .monospaced))
                        .foregroundStyle(line.color.opacity(0.9))
                        .frame(maxWidth: .infinity, alignment: .leading)
                        .padding(.horizontal, 4)
                        .padding(.vertical, 1)
                        .background(line.color.opacity(0.1))
                }
            }
        }
        .textSelection(.enabled)
        .padding(4)
        .frame(maxWidth: .infinity, alignment: .leading)
        .background(Color.primary.opacity(0.04), in: RoundedRectangle(cornerRadius: 4))
    }
}

private func editDiffView(_ d: EditToolData) -> some View {
    let removed = d.oldString.components(separatedBy: "\n").map {
        DiffLine(prefix: "-", text: $0, color: .red)
    }
    let inserted = d.newString.components(separatedBy: "\n").map {
        DiffLine(prefix: "+", text: $0, color: .green)
    }
    return DiffContentView(
        filePath: d.filePath,
        lines: removed + inserted,
        fallbackContents: [d.oldString, d.newString],
        threshold: 120
    )
}

private func writeDiffView(_ d: WriteToolData) -> some View {
    let inserted = d.content.components(separatedBy: "\n").map {
        DiffLine(prefix: "+", text: $0, color: .green)
    }
    return DiffContentView(
        filePath: d.filePath,
        lines: inserted,
        fallbackContents: [d.content],
        threshold: 160
    )
}
```

Predicted DRY metrics: edit/write diff rendering share one rendering flow; threshold differences remain configuration, not duplicated logic.

