private struct ToolResultDisplayState {
    let content: String
    let previewLineCount: Int
    let lineCount: Int
    let isTruncated: Bool
    let preview: String

    static func make(content: String, previewLineCount: Int = 20) -> ToolResultDisplayState {
        let lines = content.components(separatedBy: "\n")
        return ToolResultDisplayState(
            content: content,
            previewLineCount: previewLineCount,
            lineCount: lines.count,
            isTruncated: lines.count > previewLineCount,
            preview: lines.prefix(previewLineCount).joined(separator: "\n")
        )
    }
}

private struct ToolResultView: View {
    let state: ToolResultDisplayState
    @State private var showFull = false

    init(content: String) {
        self.state = ToolResultDisplayState.make(content: content)
    }

    var body: some View {
        VStack(alignment: .leading, spacing: 2) {
            resultLabel
            resultText
        }
    }

    private var resultLabel: some View {
        HStack(spacing: 4) {
            Text("Result")
                .font(.system(size: 9, weight: .medium))
                .foregroundStyle(.tertiary)
            if state.isTruncated {
                Button { showFull.toggle() } label: {
                    Text(showFull ? "collapse" : "\(state.lineCount) lines")
                        .font(.system(size: 9))
                        .foregroundStyle(.blue.opacity(0.7))
                }
                .buttonStyle(.plain)
            }
        }
    }

    private var resultText: some View {
        Text(showFull || !state.isTruncated ? state.content : state.preview + "\n...")
            .font(.system(size: 10, design: .monospaced))
            .foregroundStyle(.tertiary)
            .textSelection(.enabled)
            .padding(6)
            .frame(maxWidth: .infinity, alignment: .leading)
            .background(Color.primary.opacity(0.03), in: RoundedRectangle(cornerRadius: 4))
    }
}
