protocol LogViewerSessionControlling {
    func bridge(for pid: Int) -> TTYBridge?
    func detachSession(for pid: Int)
}

extension SessionManager: LogViewerSessionControlling {
    func detachSession(for pid: Int) {
        bridge(for: pid)?.detach()
        sessions.removeValue(forKey: pid)
    }
}

struct LogViewerView<VM: LogViewerState & LogViewerActions>: View {
    var sessionManager: (any LogViewerSessionControlling)?

    private var bridge: TTYBridge? {
        sessionManager?.bridge(for: agent.pid)
    }

    private var logHeader: some View {
        // Stop button action becomes:
        Button {
            sessionManager?.detachSession(for: agent.pid)
            onStop?()
        } label: {
            Image(systemName: "stop.circle.fill")
                .font(navFont)
        }
    }
}
```

